// src/pages/Dashboard.jsx
import { useNavigate } from "react-router-dom";
import { 
  Utensils, 
  Table, 
  ShoppingCart, 
  Package, 
  Users, 
  LogOut,
  Clock,
  Calendar
} from "lucide-react";
import "./Dashboard.css";

export default function Dashboard() {
  const navigate = useNavigate();

  const cerrarSesion = () => {
    localStorage.removeItem("access_token");
    localStorage.removeItem("refresh_token");
    navigate("/login");
  };

  const menu = [
    {
      titulo: "Mesas",
      subtitulo: "Control de ocupación",
      icon: Table,
      color: "#e74c3c",
      ruta: "/mesas"
    },
    {
      titulo: "Pedidos",
      subtitulo: "Gestión y seguimiento",
      icon: ShoppingCart,
      color: "#c0392b",
      ruta: "/pedidos"
    },
    {
      titulo: "Productos",
      subtitulo: "Menú del restaurante",
      icon: Utensils,
      color: "#e74c3c",
      ruta: "/productos"
    },
    {
      titulo: "Categorías",
      subtitulo: "Organización del menú",
      icon: Package,
      color: "#c0392b",
      ruta: "/categorias"
    },
    {
      titulo: "Empleados",
      subtitulo: "Gestión del personal",
      icon: Users,
      color: "#e74c3c",
      ruta: "/empleados"
    },
    {
      titulo: "Reportes",
      subtitulo: "Ventas y estadísticas",
      icon: Calendar,
      color: "#c0392b",
      ruta: "/reportes"
    }
  ];

  return (
    <div className="dashboard">
      <div className="dashboard-bg"></div>
      <div className="dashboard-overlay"></div>

      <div className="dashboard-content">
        {/* Título */}
        <div className="header">
          <h1 className="title">SOFTFOOD</h1>
          <p className="subtitle">Panel de Control del Restaurante</p>
        </div>

        {/* Grid de tarjetas clicables */}
        <div className="grid">
          {menu.map((item, index) => {
            const Icon = item.icon;
            return (
              <div
                key={index}
                className="card"
                onClick={() => navigate(item.ruta)}
                style={{ "--card-color": item.color }}
              >
                <div className="card-icon">
                  <Icon size={48} strokeWidth={1.8} />
                </div>
                <h3>{item.titulo}</h3>
                <p>{item.subtitulo}</p>
              </div>
            );
          })}
        </div>
<div 
  className="bg-white bg-opacity-10 rounded-3xl p-10 shadow-2xl hover:shadow-red-900/50 transition-all transform hover:scale-105 cursor-pointer border-4 border-transparent hover:border-orange-500 backdrop-blur-sm"
  onClick={() => window.open("/cocina", "_blank")}
>
  {/* ÍCONO 100% IGUAL QUE LOS DEMÁS */}
  <div className="text-orange-400 mb-6">
    <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-20 h-20 mx-auto">
      <path strokeLinecap="round" strokeLinejoin="round" d="M15.362 5.214A8.252 8.252 0 0112 21 8.25 8.25 0 016.038 7.048M9 8.25h6m-6 4.5h6m-6 4.5h6" />
      <path strokeLinecap="round" strokeLinejoin="round" d="M12 3v3.75m6.364.636l-1.06 1.06m-12.728 0l1.06 1.06m-.364 12.728l1.06-1.06m12.728 0l-1.06-1.06" />
    </svg>
  </div>

  <h2 className="text-4xl font-bold text-white mb-2 text-center">
    COCINA EN VIVO
  </h2>
  <p className="text-orange-200 text-lg text-center">
    Pantalla roja en tiempo real
  </p>
</div>
        {/* Botón cerrar sesión */}
        <button onClick={cerrarSesion} className="logout-btn">
          <LogOut size={20} />
          Cerrar Sesión
        </button>
      </div>
    </div>
  );
}
